import{_ as p,a0 as o,w as r,s as d,ao as i,I as l,x as a,a1 as t,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"ZOMBIES：如何在軟件開發中實現業務需求（四） | LCTT x X-CMD","titleTemplate":false,"description":"ZOMBIES：如何在軟件開發中實現業務需求（四） | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"ZOMBIES：如何在軟件開發中實現業務需求（四） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"ZOMBIES：如何在軟件開發中實現業務需求（四） | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20210204 How to implement business requirements in software development","title":"ZOMBIES：如何在軟件開發中實現業務需求（四）","tag":"202305","desc":""},"relativePath":"202305/20210204 How to implement business requirements in software development.md","filePath":"[post].md"}'),u={name:"202305/20210204 How to implement business requirements in software development.md"};function g(h,s,m,b,c,f){const n=o("Link");return r(),d("div",null,[s[22]||(s[22]=i('<h1 id="zombies-如何在軟件開發中實現業務需求-四" tabindex="-1">ZOMBIES：如何在軟件開發中實現業務需求（四） <a class="header-anchor" href="#zombies-如何在軟件開發中實現業務需求-四" aria-label="Permalink to “ZOMBIES：如何在軟件開發中實現業務需求（四）”">​</a></h1><blockquote><p>完善你的電商應用，使它能夠正確處理業務規則。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202305/30/094226xz66t662t42auuht.jpg" alt=""></p><p>在前面的文章中，我已經解釋了為什麼將編程問題看作一整羣喪屍來處理是錯誤的。我用 ZOMBIES 方法來解釋為什麼循序漸進地處理問題更好。</p><p>ZOMBIES 表示以下首字母縮寫：</p><ul><li><strong>Z</strong> – 最簡場景（Zero）</li><li><strong>O</strong> – 單元素場景（One）</li><li><strong>M</strong> – 多元素場景（Many or more complex）</li><li><strong>B</strong> – 邊界行為（Boundary behaviors）</li><li><strong>I</strong> – 接口定義（Interface definition）</li><li><strong>E</strong> – 處理特殊行為（Exercise exceptional behavior）</li><li><strong>S</strong> – 簡單場景用簡單的解決方案（Simple scenarios, simple solutions）</li></ul>',6)),l("p",null,[s[3]||(s[3]=a("在系列的前三篇文章中，我展示了 ZOMBIES 方法的前五項。第一篇中 ",-1)),t(n,{href:"https://linux.cn/article-15808-1.html"},{default:e(()=>[...s[0]||(s[0]=[a("實現了最簡場景",-1)])]),_:1}),s[4]||(s[4]=a("，它為代碼提供了最簡可行路徑。第二篇文章中執行了 ",-1)),t(n,{href:"https://linux.cn/article-15817-1.html"},{default:e(()=>[...s[1]||(s[1]=[a("單元素場景和多元素場景上的測試",-1)])]),_:1}),s[5]||(s[5]=a("。第三篇中介紹了 ",-1)),t(n,{href:"https://linux.cn/article-15859-1.html"},{default:e(()=>[...s[2]||(s[2]=[a("邊界和接口",-1)])]),_:1}),s[6]||(s[6]=a("。在本文中，我將帶你瞭解倒數第二個方法：處理特殊行為。",-1))]),s[23]||(s[23]=i(`<h3 id="處理特殊行為" tabindex="-1">處理特殊行為 <a class="header-anchor" href="#處理特殊行為" aria-label="Permalink to “處理特殊行為”">​</a></h3><p>在開發一個電子購物應用時，你需要從產品負責人或贊助商那裏瞭解需要採用什麼銷售策略。</p><p>毫無疑問，與任何電子商業活動一樣，你需要通過制定銷售策略來誘導顧客進行消費。假設有如下的銷售策略：訂單金額超過 ￥500 時可以享受一定的折扣優惠。</p><p>現在將這個銷售策略轉換為可運行期望：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Fact]</span></span>
<span class="line"><span>public void Add2ItemsTotal600GrandTotal540() {</span></span>
<span class="line"><span>        var expectedGrandTotal = 540.00;</span></span>
<span class="line"><span>        var actualGrandTotal = 0.00;</span></span>
<span class="line"><span>        Assert.Equal(expectedGrandTotal, actualGrandTotal);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>這個正面樣例表示的銷售策略是，如果訂單總額為 ￥600.00，那麼 <code>shoppingAPI</code> 會將其減價為 ￥540.00。上面的代碼偽造了一個失敗驗證用例。現在修改它，讓它能夠通過測試：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Fact]</span></span>
<span class="line"><span>public void Add2ItemsTotal600GrandTotal540() {</span></span>
<span class="line"><span>        var expectedGrandTotal = 540.00;</span></span>
<span class="line"><span>        Hashtable item = new Hashtable();</span></span>
<span class="line"><span>        item.Add(&quot;00000001&quot;, 200.00);</span></span>
<span class="line"><span>        shoppingAPI.AddItem(item);</span></span>
<span class="line"><span>        Hashtable item2 = new Hashtable();</span></span>
<span class="line"><span>        item2.Add(&quot;00000002&quot;, 400.00);</span></span>
<span class="line"><span>        shoppingAPI.AddItem(item2);</span></span>
<span class="line"><span>        var actualGrandTotal = shoppingAPI.CalculateGrandTotal();</span></span>
<span class="line"><span>        Assert.Equal(expectedGrandTotal, actualGrandTotal);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在這個正樣例中，你向購物框加入一件價值 ￥200 的商品和一件價值 ￥400 的商品，使總價達到 ￥600 。當調用 <code>CalculateGrandTotal()</code> 方法時，你期望總價是 ￥540。</p><p>這個微測試能夠通過嗎？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[xUnit.net 00:00:00.57] tests.UnitTest1.Add2ItemsTotal600GrandTotal540 [FAIL]</span></span>
<span class="line"><span>  X tests.UnitTest1.Add2ItemsTotal600GrandTotal540 [2ms]</span></span>
<span class="line"><span>  Error Message:</span></span>
<span class="line"><span>   Assert.Equal() Failure</span></span>
<span class="line"><span>Expected: 540</span></span>
<span class="line"><span>Actual: 600</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>很可惜，它失敗了。你期望的結果是 ￥540，但計算結果為 ￥600。為什麼會這樣呢？那是因為你還沒有告訴系統在訂單總價大於 ￥500 時怎麼進行折扣計算。</p><p>現在來實現折扣計算邏輯。根據上面的正樣例可知，當訂單總價為 ￥600（超過了營銷策略的閾值 ￥500）時，期望的最終總價為 ￥540。也就是説系統需要從訂單總額中減去 ￥60。剛好是是原訂單總價的 10%。因此該銷售規則就是當訂單總額超過 ￥500 時享受九折優惠。</p><p>在 <code>ShippingAPI</code> 類中實現該處理邏輯：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>private double Calculate10PercentDiscount(double total) {</span></span>
<span class="line"><span>        double discount = 0.00;</span></span>
<span class="line"><span>        if(total &gt; 500.00) {</span></span>
<span class="line"><span>                discount = (total/100) * 10;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        return discount;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>首先，檢查訂單總額是否大於 ￥500 。如果是，則計算出總額的 10%。</p><p>你還需要告訴系統怎麼從訂單總額中減去 10%。改動非常直接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>return grandTotal - Calculate10PercentDiscount(grandTotal);</span></span></code></pre></div><p>到此，所有測試都能夠通過。你又一次享受到系統處於穩態的歡愉。你的代碼通過處理特殊行為實現了需要的銷售策略。</p><h3 id="最後一步" tabindex="-1">最後一步 <a class="header-anchor" href="#最後一步" aria-label="Permalink to “最後一步”">​</a></h3><p>現在我已經介紹完 ZOMBIE 了，只剩下 S 了。我將會在最後一篇中介紹它。</p><p><em>（題圖：MJ/7f8bf5d2-54ce-4d6e-9dbf-13abf6df966a）</em></p><hr>`,22)),l("p",null,[s[8]||(s[8]=a("via: ",-1)),t(n,{href:"https://opensource.com/article/21/2/exceptional-behavior"},{default:e(()=>[...s[7]||(s[7]=[a("https://opensource.com/article/21/2/exceptional-behavior",-1)])]),_:1})]),l("p",null,[s[13]||(s[13]=a("作者：",-1)),t(n,{href:"https://opensource.com/users/alex-bunardzic"},{default:e(()=>[...s[9]||(s[9]=[a("Alex Bunardzic",-1)])]),_:1}),s[14]||(s[14]=a(" 選題：",-1)),t(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[10]||(s[10]=[a("lujun9972",-1)])]),_:1}),s[15]||(s[15]=a(" 譯者：",-1)),t(n,{href:"https://github.com/toknow-gh"},{default:e(()=>[...s[11]||(s[11]=[a("toknow-gh",-1)])]),_:1}),s[16]||(s[16]=a(" 校對：",-1)),t(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[19]||(s[19]=a("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[17]||(s[17]=[a("LCTT",-1)])]),_:1}),s[20]||(s[20]=a(" 原創編譯，",-1)),t(n,{href:"https://linux.cn/"},{default:e(()=>[...s[18]||(s[18]=[a("Linux中國",-1)])]),_:1}),s[21]||(s[21]=a(" 榮譽推出",-1))])])}const C=p(u,[["render",g]]);export{x as __pageData,C as default};
